#!/usr/bin/env python3
"""Check explicit private build and failure atomicity against an authorized font file."""
import base64,hashlib,json,pathlib,subprocess,sys,tempfile
if len(sys.argv)!=2:raise SystemExit('Usage: python3 test_private_font_build.py AUTHORIZED_LOCAL_FONT')
root=pathlib.Path(__file__).resolve().parent;font=pathlib.Path(sys.argv[1]).resolve(strict=True);fontbytes=font.read_bytes();sha=hashlib.sha256(fontbytes).hexdigest();alias='gdprivate-'+sha[:16]
with tempfile.TemporaryDirectory() as tmp:
    d=pathlib.Path(tmp);project=d/'project.json';project.write_text(json.dumps({'schema':1,'title':'Private build test','slides':[{'id':'s1','html':'<p data-source-id="s1-o1">Test text</p>'}]}));mapping=d/'mapping.json';mapping.write_text(json.dumps({'targets':[{'sourceId':'s1-o1','family':alias,'weight':300}]}));selection=d/'selection.json';selection.write_text(json.dumps({'sources':[{'requirements':[{'resolution':{'status':'exact-face-candidate','cssFamilyAlias':alias,'weight':300,'italic':False,'path':str(font),'sha256':sha}}]}]}));inputs={p:hashlib.sha256(p.read_bytes()).hexdigest() for p in [project,mapping,selection,font]}
    def run(out,sel=selection,mp=mapping,extra=(),proj=project):return subprocess.run([sys.executable,str(root/'build_private_fonts.py'),str(proj),str(out),'--font-map',str(mp),'--selection',str(sel),*extra],capture_output=True,text=True)
    out=d/'built.html';r=run(out);assert r.returncode==0,r.stderr;html=out.read_text();assert font.as_uri() in html and alias in html;assert base64.b64encode(fontbytes).decode() not in html
    before=out.read_bytes();assert 'id="gd-private-font-map"' in html;assert run(out).returncode!=0 and out.read_bytes()==before
    bad=d/'bad-selection.json';data=json.loads(selection.read_text());data['sources'][0]['requirements'][0]['resolution']['sha256']='0'*64;bad.write_text(json.dumps(data));badout=d/'bad.html';bad_result=run(badout,sel=bad);assert bad_result.returncode!=0 and not badout.exists() and '"status": "built"' not in bad_result.stdout
    broken=d/'missing-target.json';broken.write_text(json.dumps({'targets':[{'sourceId':'s1-missing','family':alias,'weight':300}]}));missing=d/'missing.html';assert run(missing,mp=broken).returncode!=0 and not missing.exists()
    wrong=d/'wrong-weight.json';wrong.write_text(json.dumps({'targets':[{'sourceId':'s1-o1','family':alias,'weight':400}]}));wrongout=d/'wrong.html';assert run(wrongout,mp=wrong).returncode!=0 and not wrongout.exists()
    changed_font=d/'font-copy.otf';changed_font.write_bytes(fontbytes);changed_selection=d/'changed-selection.json';data=json.loads(selection.read_text());data['sources'][0]['requirements'][0]['resolution']['path']=str(changed_font);changed_selection.write_text(json.dumps(data));changed_font.write_bytes(fontbytes+b'changed');changed_out=d/'changed.html';assert run(changed_out,sel=changed_selection).returncode!=0 and not changed_out.exists()
    # Synthetic fixtures test gating only; they do not constitute visual approval.
    frame=d/'frame.png';frame.write_bytes(base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/aWQAAAAASUVORK5CYII='));outline=d/'outline.txt';outline.write_text('fixture')
    fields={key:'fixture' for key in ['sourceId','purpose','emphasis','readingOrder','groups','density','editability','works','problem','capacity','technicalRisk']}
    fields.update({'slideId':'s1','decision':'preserve','sourceOutline':'outline.txt','visualReview':{'reviewed':True,'observation':'synthetic test only','candidateRender':'frame.png','candidateRenderSha256':hashlib.sha256(frame.read_bytes()).hexdigest(),'projectSha256':hashlib.sha256(project.read_bytes()).hexdigest(),'privateFontMapSha256':hashlib.sha256(mapping.read_bytes()).hexdigest(),'privateFontSelectionSha256':hashlib.sha256(selection.read_bytes()).hexdigest()}})
    plan=d/'plan.json';plan.write_text(json.dumps({'inputKind':'outline','slides':[fields]}));final=d/'final.html';assert run(final,extra=['--final','--composition-plan',str(plan)]).returncode==0
    revised=d/'revised-map.json';data=json.loads(mapping.read_text());data['revision']='changed';revised.write_text(json.dumps(data));mismatch=d/'final-mismatch.html';assert run(mismatch,mp=revised,extra=['--final','--composition-plan',str(plan)]).returncode!=0 and not mismatch.exists()
    no_plan=d/'final-no-plan.html';assert run(no_plan,extra=['--final']).returncode!=0 and not no_plan.exists()
    clip=d/'clip.mp4';clip.write_bytes(b'fake video fixture');media_project=d/'media-project.json';data=json.loads(project.read_text());data['slides'][0]['html']+='<video src=\"clip.mp4\"></video>';media_project.write_text(json.dumps(data));media_out=d/'media.html';r=run(media_out,extra=['--external-media'],proj=media_project);assert r.returncode==0,r.stderr
    media_dir=d/'media_media';manifest=json.loads((media_dir/'manifest.json').read_text());entry=manifest['files'][0];assert (media_dir/entry['path']).read_bytes()==clip.read_bytes();assert entry['sha256']==hashlib.sha256(clip.read_bytes()).hexdigest();assert 'media_media/'+entry['path'] in media_out.read_text()
    invalid_media=d/'bad-media.html';assert run(invalid_media,mp=broken,extra=['--external-media'],proj=media_project).returncode!=0 and not invalid_media.exists() and not (d/'bad-media_media').exists()
    conflict=d/'blocked_media';conflict.mkdir();sentinel=conflict/'keep';sentinel.write_text('unchanged');blocked=d/'blocked.html';assert run(blocked,extra=['--external-media'],proj=media_project).returncode!=0 and not blocked.exists() and sentinel.read_text()=='unchanged'
    for p,old in inputs.items():assert hashlib.sha256(p.read_bytes()).hexdigest()==old,str(p)
    assert not list(d.glob('.gd-private-build-*'))
print('PASS: private font hash/input/output guards; --final binds map and selection; --external-media package and conflict rollback')
